const se = Application('System Events');
const out = [];
for (const name of ["zen", "Zen", "Zen Browser"]) {
  if (!se.processes.whose({name: name}).length) continue;
  const proc = se.processes.byName(name);
  if (!proc.windows.length) continue;
  const queue = [proc.windows[0]];
  let seen = 0;
  while (queue.length && seen < 2500) {
    const el = queue.shift(); seen += 1;
    for (const f of ['name', 'description', 'value', 'title']) {
      try { const v = el[f](); if (typeof v === 'string' && v) out.push(v); } catch (e) {}
    }
    try { if (el.role() === 'AXWebArea') out.push('url=' + el.attributes.byName('AXURL').value()); } catch (e) {}
    try { for (const child of el.uiElements()) queue.push(child); } catch (e) {}
  }
}
out.join(' | ').toLowerCase();

